{
  "cvars": {
    "ivs": [
      {
        "description": "Binary indicator for player skin tone category derived from two independent raters' skin-tone ratings (5-point scale normalized to [0,1]). Coded as 1 for dark skin (AvgSkin >= 0.75) and 0 for light skin (AvgSkin <= 0.25). Intermediate ratings are excluded so the contrast is between clearly light and clearly dark skin tones.",
        "columns": [
          "SkinDark"
        ]
      }
    ],
    "dv": {
      "description": "Count of red cards the player received from the referee in the player-referee dyad (outcome). This is modeled as a count with exposure equal to the number of games in the dyad.",
      "columns": [
        "redCards"
      ]
    },
    "controls": [
      {
        "description": "Number of games that the player and referee encountered each other (exposure). Modeled as an offset (log(games)) in the count model so we estimate red-card rate per game.",
        "is_moderator": false,
        "columns": [
          "games"
        ]
      },
      {
        "description": "Average continuous skin tone score (mean of rater1 and rater2, normalized 0-1). Included for sensitivity / secondary analyses.",
        "is_moderator": false,
        "columns": [
          "AvgSkin"
        ]
      },
      {
        "description": "Player age (years) at approximate mid-season date (used to control for age-related differences in play style / referee treatment).",
        "is_moderator": false,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Player height (cm), a physical covariate that may correlate with playing style or fouls.",
        "is_moderator": false,
        "columns": [
          "height"
        ]
      },
      {
        "description": "Player weight (kg), a physical covariate.",
        "is_moderator": false,
        "columns": [
          "weight"
        ]
      },
      {
        "description": "Player position on the field (categorical). Included as categorical controls via C(position) in the model because different positions receive different referee sanctions.",
        "is_moderator": false,
        "columns": [
          "position"
        ]
      },
      {
        "description": "League country where the match was played (categorical). Controls for league-specific enforcement / style.",
        "is_moderator": false,
        "columns": [
          "leagueCountry"
        ]
      },
      {
        "description": "Referee-country mean implicit bias score (IAT): higher values correspond to faster white|good, black|bad associations. Country-level covariate for referees' societal-level implicit bias.",
        "is_moderator": false,
        "columns": [
          "meanIAT"
        ]
      },
      {
        "description": "Referee-country mean explicit bias score (racial thermometer): higher values correspond to warmer feelings toward whites vs blacks. Country-level covariate for referees' societal-level explicit bias.",
        "is_moderator": false,
        "columns": [
          "meanExp"
        ]
      },
      {
        "description": "Referee unique identifier. Used for clustering standard errors at the referee level (accounts for correlation across dyads with the same referee).",
        "is_moderator": false,
        "columns": [
          "refNum"
        ]
      },
      {
        "description": "Referee country identifier (kept for potential descriptive checks).",
        "is_moderator": false,
        "columns": [
          "refCountry"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform original dataset into the analytic dataframe used for modeling.\n\n    Produced columns (exact names used by the model):\n      - redCards: count outcome (numeric)\n      - games: number of games in dyad (numeric, used as offset)\n      - AvgSkin: mean of rater1 and rater2 (continuous 0-1)\n      - SkinDark: binary indicator (1 = dark skin (AvgSkin >= 0.75), 0 = light skin (AvgSkin <= 0.25)). Rows with intermediate AvgSkin are removed.\n      - age: player age in years (numeric)\n      - height, weight: numeric controls\n      - position: categorical control (kept as-is for formula-based categorical handling)\n      - leagueCountry: categorical control\n      - meanIAT, meanExp: country-level bias measures (numeric)\n      - refNum, refCountry: referee identifiers used for clustering / descriptive checks\n    \"\"\"\n    df = df.copy()\n\n    # Ensure required columns exist and drop rows with missing core values\n    required_core = ['rater1', 'rater2', 'redCards', 'games']\n    df = df.dropna(subset=required_core)\n\n    # Compute average skin rating\n    df['AvgSkin'] = (pd.to_numeric(df['rater1'], errors='coerce') + pd.to_numeric(df['rater2'], errors='coerce')) / 2.0\n\n    # Define clear light and clear dark thresholds and create binary SkinDark\n    # Normalized scale assumed (0.0..1.0) with five discrete values; thresholds chosen to select clear light and clear dark\n    df['SkinDark'] = np.where(df['AvgSkin'] >= 0.75, 1,\n                               np.where(df['AvgSkin'] <= 0.25, 0, np.nan))\n\n    # Keep only rows that are clearly light or clearly dark to address measurement noise and create a clean contrast\n    df = df[df['SkinDark'].notna()].copy()\n    df['SkinDark'] = df['SkinDark'].astype(int)\n\n    # Parse birthday and compute age at a reference date (season midpoint ~ 2013-01-01)\n    # birthday format documented as 'dd.mm.yyyy'\n    df['birthday'] = pd.to_datetime(df['birthday'], format='%d.%m.%Y', errors='coerce')\n    reference_date = pd.to_datetime('2013-01-01')\n    df['age'] = ((reference_date - df['birthday']).dt.days / 365.25).astype(float)\n\n    # Ensure numeric types for physical covariates and outcome/exposure\n    df['height'] = pd.to_numeric(df['height'], errors='coerce')\n    df['weight'] = pd.to_numeric(df['weight'], errors='coerce')\n    df['games'] = pd.to_numeric(df['games'], errors='coerce')\n    df['redCards'] = pd.to_numeric(df['redCards'], errors='coerce')\n\n    # Ensure bias measures are numeric\n    df['meanIAT'] = pd.to_numeric(df['meanIAT'], errors='coerce')\n    df['meanExp'] = pd.to_numeric(df['meanExp'], errors='coerce')\n\n    # Keep only rows with the covariates needed for the model\n    keep_cols = ['redCards', 'games', 'AvgSkin', 'SkinDark', 'age', 'height', 'weight',\n                 'position', 'leagueCountry', 'meanIAT', 'meanExp', 'refNum', 'refCountry']\n\n    df = df.dropna(subset=keep_cols)\n\n    # Ensure games > 0 for offset (dataset minimum is 1 according to schema, but double-check)\n    df = df[df['games'] > 0].copy()\n\n    # Return a dataframe with exactly the columns the model code expects\n    return df[keep_cols]\n",
  "m_code": "def model(df: pd.DataFrame):\n    \"\"\"\n    Fit a negative binomial GLM for red card counts with an offset for number of games.\n\n    Primary model (tests research question):\n      redCards ~ SkinDark + age + height + weight + C(position) + C(leagueCountry) + meanIAT + meanExp\n      offset = log(games)\n\n    Standard errors are clustered by referee (refNum) to account for correlations across dyads judged by the same referee.\n\n    Returns:\n      - fitted results object from statsmodels (GLMResults)\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Copy dataframe to avoid side-effects\n    df = df.copy()\n\n    # Formula: main independent variable is SkinDark (1 dark, 0 light). Position and leagueCountry treated as categorical.\n    formula = 'redCards ~ SkinDark + age + height + weight + C(position) + C(leagueCountry) + meanIAT + meanExp'\n\n    # Build and fit the negative binomial GLM with log(games) as an offset (exposure)\n    # Note: statsmodels expects the offset to be provided as a numeric array; we give log(games)\n    model = smf.glm(formula=formula,\n                    data=df,\n                    family=sm.families.NegativeBinomial(),\n                    offset=np.log(df['games']))\n\n    # Fit with cluster-robust SEs by refNum (referee)\n    results = model.fit(cov_type='cluster', cov_kwds={'groups': df['refNum']})\n\n    # Print summary for quick inspection; return the results object for programmatic use\n    print(results.summary())\n    return results\n"
}
